const $=id=>document.getElementById(id);
const LEVELS=[
 {title:'O animal esquecido',description:'Encontre o único animal que recebeu zero refeições hoje. Sua consulta deve retornar apenas esse animal, identificado pelo nome ou id.',hints:['Há animais com a rotina incompleta, mas isso não significa que ficaram sem comida.','Compare a quantidade de refeições. Você procura quem não recebeu nenhuma.'],sql:'SELECT id, animal, especie, vezes_alimentado\nFROM animais\nWHERE vezes_alimentado = 0;',explanation:'WHERE filtra os registros pela condição desejada. Zero refeições identifica quem não foi alimentado.'},
 {title:'O veterano do zoológico',description:'Descubra qual animal é o mais velho do zoológico. Retorne somente esse animal, com seu nome ou id. A coluna idade guarda a idade em anos.',hints:['O veterano pode pertencer a uma espécie que vive muito mais tempo do que outras.','Você precisa comparar as idades de todos os animais, não apenas de uma espécie.'],sql:'SELECT id, animal, idade\nFROM animais\nORDER BY idade DESC\nLIMIT 1;',explanation:'DESC coloca as maiores idades primeiro. LIMIT 1 mantém apenas o animal mais velho. Uma consulta com MAX(idade) também pode funcionar, se retornar sua identificação.'},
 {title:'Os três caçulas',description:'Encontre os três animais mais novos do zoológico e mostre-os em ordem crescente de idade: do mais novo ao menos novo. Inclua o nome ou id de cada um.',hints:['Procure as menores idades de todo o zoológico.','Escolher três animais e ordená-los são duas partes do desafio. O primeiro deve ser o mais novo.'],sql:'SELECT id, animal, idade\nFROM animais\nORDER BY idade ASC\nLIMIT 3;',explanation:'ASC organiza do menor para o maior. LIMIT 3 mantém os três primeiros, que são os animais mais novos.'},
 {title:'Os veteranos, em outra ordem',description:'Selecione os três animais mais velhos do zoológico. Depois, apresente esses três em ordem crescente de idade: do menos velho ao mais velho. Inclua nome ou id.',hints:['Ordenar todo o zoológico em ordem crescente e pegar três registros encontra os mais novos — não os veteranos.','Primeiro escolha quem faz parte do grupo dos três mais velhos; só depois organize esse grupo em ordem crescente.'],sql:'SELECT id, animal, idade\nFROM (\n  SELECT id, animal, idade\n  FROM animais\n  ORDER BY idade DESC\n  LIMIT 3\n) AS veteranos\nORDER BY idade ASC;',explanation:'A consulta interna seleciona os três mais velhos. A externa organiza somente esse grupo em ordem crescente. CTEs e outras consultas equivalentes também são aceitas.'},
 {title:'Os dois gigantes',description:'Encontre os dois animais mais pesados de todo o zoológico. A coluna kg guarda o peso em quilogramas. Inclua nome ou id; a ordem entre os dois é livre.',hints:['O nome da espécie é uma pista, mas são os pesos individuais que confirmam os dois gigantes.','Compare os pesos de todos os animais e mantenha somente os dois maiores.'],sql:'SELECT id, animal, kg\nFROM animais\nORDER BY kg DESC\nLIMIT 2;',explanation:'DESC coloca os maiores pesos primeiro. LIMIT 2 retorna somente os dois animais mais pesados.'},
{"title": "Espécies com mais experiência", "description": "Encontre as espécies cuja idade média é maior que 20 anos. Mostre a espécie e sua idade média, da maior média para a menor. Se arredondar a média, use duas casas decimais.", "hints": ["Uma espécie pode ter jovens e veteranos. Compare a média do grupo, não a idade de um único animal.", "Agrupe primeiro por espécie. A condição deve ser aplicada à média de cada grupo."], "sql": "SELECT especie, AVG(idade) AS media_idade\nFROM animais\nGROUP BY especie\nHAVING AVG(idade) > 20\nORDER BY media_idade DESC;", "explanation": "GROUP BY reúne os animais de cada espécie. AVG calcula a idade média do grupo. HAVING mantém só as médias acima de 20 anos. A ordenação mostra a maior média primeiro."},
{"title": "Um gigante de cada espécie", "description": "Encontre o animal mais pesado de cada uma das 10 espécies. Retorne um animal por espécie, identificado por nome ou id, e organize os 10 do mais pesado ao mais leve.", "hints": ["Escolher os dez maiores pesos do zoológico pode repetir espécies. Você precisa de um vencedor em cada grupo.", "Descubra o maior peso de cada espécie e relacione esse peso ao animal correspondente. Uma subconsulta, JOIN ou função de janela pode ajudar."], "sql": "SELECT animais.id, animais.animal, animais.especie, animais.kg\nFROM animais\nJOIN (\n  SELECT especie, MAX(kg) AS maior_peso\n  FROM animais\n  GROUP BY especie\n) AS maiores\n  ON animais.especie = maiores.especie\n  AND animais.kg = maiores.maior_peso\nORDER BY animais.kg DESC;", "explanation": "A subconsulta encontra o maior peso de cada espécie. JOIN liga esses resultados aos animais. ON e AND exigem a mesma espécie e o peso máximo daquele grupo. Assim, a consulta identifica um gigante por espécie e organiza os dez pelo peso."}
];
const ANSWER_GUIDES=[
 ['SELECT animal, vezes_alimentado — selecionar o nome e as refeições.', 'FROM animais — buscar na tabela animais.', 'WHERE vezes_alimentado = 0 — mostrar apenas quem recebeu zero refeições.'],
 ['SELECT animal, idade — selecionar o nome e a idade.', 'FROM animais — buscar na tabela animais.', 'ORDER BY idade DESC — ordenar do mais velho ao mais novo.', 'LIMIT 1 — mostrar somente o primeiro.'],
 ['SELECT animal, idade — selecionar o nome e a idade.', 'FROM animais — buscar na tabela animais.', 'ORDER BY idade ASC — ordenar do mais novo ao mais velho.', 'LIMIT 3 — mostrar somente os três primeiros.'],
 ['Dentro dos parênteses: SELECT animal, idade FROM animais — buscar nomes e idades.', 'Ainda dentro: ORDER BY idade DESC LIMIT 3 — escolher os três mais velhos.', 'Fora: SELECT animal, idade FROM (...) AS veteranos — consultar o grupo; AS dá um nome a ele.', 'No final: ORDER BY idade ASC — ordenar esse grupo do menos velho ao mais velho.'],
 ['SELECT animal, kg — selecionar o nome e o peso.', 'FROM animais — buscar na tabela animais.', 'ORDER BY kg DESC — ordenar do mais pesado ao mais leve.', 'LIMIT 2 — mostrar somente os dois primeiros.'],
["SELECT especie, AVG(idade) AS media_idade — selecionar a espécie e calcular sua idade média; AS dá um nome ao resultado.", "FROM animais — buscar na tabela animais.", "GROUP BY especie — agrupar por espécie.", "HAVING AVG(idade) > 20 — manter grupos com média acima de 20.", "ORDER BY media_idade DESC — ordenar da maior média para a menor."],
["Na subconsulta: SELECT especie, MAX(kg) FROM animais GROUP BY especie — encontrar o maior peso de cada espécie.", "Com AS, chame a subconsulta de maiores e o peso de maior_peso — dar nomes aos resultados.", "Na consulta externa: SELECT e FROM animais — buscar os animais.", "JOIN (...) AS maiores — unir os animais ao resultado da subconsulta.", "ON compara a espécie; AND compara o peso — manter o animal que corresponde ao maior peso de seu grupo.", "ORDER BY animais.kg DESC — ordenar do mais pesado ao mais leve."]
];
const ANSWER_NOTES=[
 'WHERE = onde / condição. O sinal = significa igual a.',
 'ORDER BY = ordenar por. DESC = decrescente. LIMIT = limitar.',
 'ORDER BY = ordenar por. ASC = crescente. LIMIT = limitar.',
 'Faça primeiro a consulta interna. Depois ordene o grupo na consulta externa. DESC = decrescente; ASC = crescente.',
 'ORDER BY = ordenar por. DESC = decrescente. LIMIT = limitar.',
"AVG = média; AS = apelido; GROUP BY = agrupar por; HAVING = condição dos grupos; DESC = decrescente.",
"MAX = maior valor; JOIN = unir; ON = condição da união; AND = e; DESC = decrescente."
];
const COMMAND_TRANSLATIONS=[[["SELECT", "selecionar as colunas"], ["FROM", "buscar na tabela"], ["WHERE", "filtrar por uma condição"], ["=", "igual a"]], [["SELECT", "selecionar as colunas"], ["FROM", "buscar na tabela"], ["ORDER BY", "ordenar por"], ["DESC", "decrescente: maior para menor"], ["LIMIT 1", "limitar a um registro"], ["MAX", "maior valor; alternativa citada acima"]], [["SELECT", "selecionar as colunas"], ["FROM", "buscar na tabela"], ["ORDER BY", "ordenar por"], ["ASC", "crescente: menor para maior"], ["LIMIT 3", "limitar a três registros"]], [["SELECT", "selecionar as colunas"], ["FROM", "buscar na tabela ou no grupo da subconsulta"], ["ORDER BY", "ordenar por"], ["DESC", "decrescente: escolher os mais velhos primeiro"], ["LIMIT 3", "limitar a três registros"], ["AS veteranos", "dar o nome veteranos ao grupo"], ["ASC", "crescente: ordenar o grupo do menos velho ao mais velho"]], [["SELECT", "selecionar as colunas"], ["FROM", "buscar na tabela"], ["ORDER BY", "ordenar por"], ["DESC", "decrescente: maior peso primeiro"], ["LIMIT 2", "limitar a dois registros"]], [["SELECT", "selecionar as colunas"], ["AVG", "calcular a média"], ["AS media_idade", "dar o nome media_idade ao resultado"], ["FROM", "buscar na tabela"], ["GROUP BY", "agrupar por"], ["HAVING", "filtrar os grupos depois do cálculo"], [">", "maior que"], ["ORDER BY", "ordenar por"], ["DESC", "decrescente: maior média primeiro"]], [["SELECT", "selecionar as colunas"], ["FROM", "buscar na tabela"], ["MAX", "encontrar o maior valor"], ["GROUP BY", "agrupar por espécie"], ["AS", "dar um nome ao resultado ou grupo"], ["JOIN", "unir os resultados"], ["ON", "definir a condição da união"], ["AND", "e: exigir as duas condições"], ["=", "igual a"], ["ORDER BY", "ordenar por"], ["DESC", "decrescente: maior peso primeiro"]]];
let SQL,db,target,level=0,won=false,consultas=0,pistas=0,history=[];
function message(text,type=''){$('feedback').textContent=text;$('feedback').className=type;}
function drawLevel(){
 $('steps').replaceChildren();LEVELS.forEach((l,i)=>{const d=document.createElement('div');d.className='step'+(i===level?' active':'');const b=document.createElement('b');b.textContent=i<level||i===level&&won?'✓':i+1;const s=document.createElement('span');s.textContent=l.title;d.append(b,s);$('steps').append(d);});
 $('mission-number').textContent=`NÍVEL ${level+1} DE ${LEVELS.length}`;$('mission-title').textContent=LEVELS[level].title;$('mission-text').textContent=LEVELS[level].description;
 $('hint').disabled=won||pistas>=2;$('hint').textContent=pistas>=2?'Duas pistas consultadas':'💡 Preciso de uma pista';
}
function render(results){$('results').replaceChildren();if(!results.length){$('row-count').textContent='0 registros';$('results').textContent='Nenhum registro encontrado. Revise sua consulta.';return;}const r=results[0];$('row-count').textContent=`${r.values.length} registro${r.values.length===1?'':'s'}`;const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');r.columns.forEach(c=>{const th=document.createElement('th');th.textContent=c;tr.append(th);});head.append(tr);table.append(head);const body=document.createElement('tbody');r.values.forEach(row=>{const tr=document.createElement('tr');row.forEach(v=>{const td=document.createElement('td');td.textContent=v===null?'NULL':String(v);tr.append(td);});body.append(tr);});table.append(body);$('results').append(table);}
function expectedAnimals(){const all=ANIMAIS.slice();if(level===0)return [target];if(level===1)return all.sort((a,b)=>b.idade-a.idade).slice(0,1);if(level===2)return all.sort((a,b)=>a.idade-b.idade).slice(0,3);if(level===3)return all.sort((a,b)=>b.idade-a.idade).slice(0,3).sort((a,b)=>a.idade-b.idade);if(level===4)return all.sort((a,b)=>b.kg-a.kg).slice(0,2);const bySpecies=new Map();for(const a of all){if(!bySpecies.has(a.especie)||a.kg>bySpecies.get(a.especie).kg)bySpecies.set(a.especie,a);}return [...bySpecies.values()].sort((a,b)=>b.kg-a.kg);}
function resultIds(r,q){
 const idColumns=new Set(['id']);for(const match of q.matchAll(/\bid\s+AS\s+["`\[]?(\w+)/gi))idColumns.add(match[1].toLowerCase());
 return r.values.map(row=>{
  const names=row.filter(v=>typeof v==='string'&&ANIMAIS.some(a=>a.animal===v));const byName=names.length===1?ANIMAIS.find(a=>a.animal===names[0]):null;
  const ix=r.columns.findIndex(c=>idColumns.has(c.toLowerCase()));const byId=ix>=0?ANIMAIS.find(a=>a.id===row[ix]):null;
  if(byName&&byId&&byName.id!==byId.id)return null;
  return (byName||byId)?.id??null;
 });
}
function expectedSpecies(){const groups=new Map();for(const a of ANIMAIS){if(!groups.has(a.especie))groups.set(a.especie,[]);groups.get(a.especie).push(a.idade);}return [...groups].map(([especie,idades])=>({especie,media:idades.reduce((s,n)=>s+n,0)/idades.length})).filter(g=>g.media>20).sort((a,b)=>b.media-a.media);}
function correctSpecies(r){const expected=expectedSpecies();if(r.values.length!==expected.length)return false;return r.values.every((row,i)=>{const labels=row.filter(v=>typeof v==='string'&&ANIMAIS.some(a=>a.especie===v));return labels.length===1&&labels[0]===expected[i].especie&&row.some(v=>typeof v==='number'&&Math.abs(v-expected[i].media)<0.00501);});}
function showTranslations(){const list=$('suggested-translations');list.replaceChildren();for(const [command,meaning] of COMMAND_TRANSLATIONS[level]){const li=document.createElement('li'),code=document.createElement('code'),span=document.createElement('span');code.textContent=command;span.textContent=' — '+meaning;li.append(code,span);list.append(li);}}
function correct(r,q){if(!r)return false;if(level===5)return correctSpecies(r);const expected=expectedAnimals().map(a=>a.id);if(r.values.length!==expected.length)return false;const ids=resultIds(r,q);if(new Set(ids).size!==expected.length||ids.includes(null))return false;return level===2||level===3||level===6?ids.every((id,i)=>id===expected[i]):expected.every(id=>ids.includes(id));}
function celebrate(){won=true;history[level]={consultas,pistas};$('celebration').hidden=false;$('winner-name').textContent=level===0?`Você encontrou ${target.animal}!`:'Resultado correto!';$('winner-details').textContent=`Nível ${level+1} concluído com ${consultas} consulta${consultas===1?'':'s'} e ${pistas} pista${pistas===1?'':'s'}. Sua consulta foi aceita pelo resultado.`;$('suggested-query').textContent=LEVELS[level].sql;$('suggested-explanation').textContent=LEVELS[level].explanation;showTranslations();$('next').hidden=level===LEVELS.length-1;$('finish').hidden=level!==LEVELS.length-1;$('rescue').hidden=level!==0;if(level===0)care();if(level===LEVELS.length-1){$('finish').textContent=`🏅 Você concluiu os ${LEVELS.length} níveis! Total: ${history.reduce((s,h)=>s+h.consultas,0)} consultas e ${history.reduce((s,h)=>s+h.pistas,0)} pistas. Clique em Recomeçar para jogar novamente.`;}drawLevel();message('Parabéns! Você resolveu este nível. 🏆','success');}
function cleanSQL(q){return q.replace(/'(?:''|[^'])*'/g,"''").replace(/\/\*[\s\S]*?\*\//g,' ').replace(/--[^\n]*/g,' ');}
function execute(){const q=$('query').value.trim();if(!q){message('Digite sua consulta SQL.','error');return;}let readDb;try{const safe=cleanSQL(q);if(!/^\s*(SELECT|WITH)\b/i.test(safe))throw Error('Use SELECT ou uma consulta com WITH para pesquisar.');if(/\b(?:INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|ATTACH|DETACH|PRAGMA|REPLACE)\b/i.test(safe))throw Error('O editor aceita apenas consultas de leitura.');readDb=new SQL.Database(db.export());let count=0;for(const stmt of readDb.iterateStatements(q))count++;if(count!==1)throw Error('Execute apenas uma consulta por vez.');const result=readDb.exec(q);if(!won)consultas++;render(result);if(correct(result[0],q)){if(!won)celebrate();else message('Consulta equivalente aceita. O resultado continua correto!','success');}else message(level===5?'Consulta executada. Confira as espécies, suas médias e a ordem decrescente pedida.':'Consulta executada. Confira os animais, a quantidade e a ordem pedida. Inclua nome ou id para identificar cada animal.');}catch(e){message('Vamos ajustar: '+e.message,'error');}finally{if(readDb)readDb.close();}}
function counter(){return db.exec(`SELECT vezes_alimentado FROM animais WHERE id=${target.id}`)[0].values[0][0];}
function care(){const n=counter();$('rescue-text').textContent=`${target.animal} · ${target.especie} · ${n} de 3 refeições registradas hoje.`;$('feed').disabled=n>=3;$('feed').textContent=n>=3?'Três refeições registradas ✓':'Registrar uma alimentação (+1)';}
$('run').onclick=execute;$('hint').onclick=()=>{if(won||pistas>=2)return;$('hint-text').hidden=false;$('hint-text').textContent=LEVELS[level].hints[pistas++];drawLevel();};
$('example').onclick=()=>{$('hint-text').hidden=false;$('hint-text').textContent='SELECT escolhe as colunas, FROM informa a tabela e WHERE aplica uma condição. ORDER BY organiza os registros e LIMIT restringe a quantidade. Você decide como combinar esses comandos.';};
$('answer').onclick=()=>{const panel=$('answer-panel');panel.hidden=!panel.hidden;$('answer').setAttribute('aria-expanded',String(!panel.hidden));if(panel.hidden)return;$('answer-steps').replaceChildren();for(const text of ANSWER_GUIDES[level]){const li=document.createElement('li');li.textContent=text;$('answer-steps').append(li);}$('answer-query').textContent=LEVELS[level].sql;$('answer-explanation').textContent=ANSWER_NOTES[level];};
$('query').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();if(db)execute();}});
$('feed').onclick=()=>{if(level!==0||!won)return;db.run(`UPDATE animais SET vezes_alimentado=vezes_alimentado+1 WHERE id=${target.id} AND vezes_alimentado<3`);care();message('Alimentação registrada. Você já pode avançar para o próximo nível.','success');};
function clearLevel(){$('answer-panel').hidden=true;$('answer-solution').open=false;$('answer').setAttribute('aria-expanded','false');won=false;consultas=0;pistas=0;$('query').value='';$('hint-text').hidden=true;$('celebration').hidden=true;$('rescue').hidden=true;$('finish').hidden=true;$('results').innerHTML='<div class="empty">🔎<p>Escolha sua consulta e descubra o resultado.</p></div>';$('row-count').textContent='Nenhuma consulta ainda';drawLevel();}
$('next').onclick=()=>{if(won&&level<LEVELS.length-1){level++;clearLevel();message('Novo nível liberado. Os dados do zoológico foram preservados.');}};
function reset(){if(db)db.close();db=new SQL.Database();db.run('CREATE TABLE animais (id INTEGER PRIMARY KEY, animal TEXT NOT NULL UNIQUE, especie TEXT NOT NULL, vezes_alimentado INTEGER NOT NULL CHECK(vezes_alimentado BETWEEN 0 AND 3), idade INTEGER NOT NULL CHECK(idade>0), kg REAL NOT NULL UNIQUE CHECK(kg>0))');target=ANIMAIS[Math.floor(Math.random()*ANIMAIS.length)];const stmt=db.prepare('INSERT INTO animais VALUES (?, ?, ?, ?, ?, ?)');for(const a of ANIMAIS)stmt.run([a.id,a.animal,a.especie,a.id===target.id?0:Math.max(1,a.vezes_alimentado),a.idade,a.kg]);stmt.free();level=0;history=[];clearLevel();message('Nível 1 pronto. Há exatamente um animal sem refeições.');}
$('restart').onclick=()=>{if(db&&confirm('Recomeçar os sete níveis? O progresso e as refeições serão reiniciados.'))reset();};drawLevel();initSqlJs({locateFile:f=>'vendor/'+f}).then(engine=>{SQL=engine;reset();$('run').disabled=false;$('run').textContent='Executar consulta →';}).catch(()=>message('Não foi possível carregar o banco. Recarregue a página.','error'));
